package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.content.Context;import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ParticleMotionHotfixTest {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("preferences",0).edit().clear().commit();}
 @Test public void defaultPathsUseTwentyPercentCurvesAndFifteenPercentRangeAndCanBeStraight(){EffectSettings p=new EffectSettings(c);assertEquals(20,p.turbulencePercent);assertEquals(15,p.arcPercent);assertEquals(100,p.particleSizePercent);int curves=0;for(int i=0;i<100;i++)if(ParticleMotion.curved(i,p))curves++;assertEquals(20,curves);AppPreferences.set(c,"fx_turbulence","off");p=new EffectSettings(c);for(int i=0;i<150;i++)assertFalse(ParticleMotion.curved(i,p));}
 @Test public void curveIsContinuousBoundedAndRejoinsBothEndpoints(){for(int id=0;id<150;id++){assertEquals(0,ParticleMotion.offset(0,id),.00001);assertEquals(0,ParticleMotion.offset(1,id),.00001);for(int n=1;n<100;n++){float t=n/100f,offset=ParticleMotion.offset(t,id);assertTrue(Math.abs(offset)<=1.00001);assertTrue(Math.abs(ParticleMotion.offset(t+.0001f,id)-offset)<.002);float numerical=(ParticleMotion.offset(t+.0001f,id)-ParticleMotion.offset(t-.0001f,id))/.0002f;assertEquals(numerical,ParticleMotion.slope(t,id),.025);}}}
 @Test public void parameterBoundsPreviewAndResetPreserveIndependentWindowControls(){AppPreferences.set(c,"fx_particle_size","999");AppPreferences.set(c,"fx_arc_percent","-1");AppPreferences.set(c,"fx_window_speed","999");AppPreferences.set(c,"fx_window_strength","0");EffectSettings p=new EffectSettings(c);assertEquals(300,p.particleSizePercent);assertEquals(0,p.arcPercent);assertEquals(3,p.windowSpeed,.0001);assertEquals(0,p.windowStrength);assertEquals(300,p.previewAir(true).particleSizePercent);assertEquals(3,p.previewCharge(4,true).windowSpeed,.0001);EffectSettings.defaults(c);p=new EffectSettings(c);assertEquals(100,p.particleSizePercent);assertEquals(60,p.windowStrength);assertEquals(1,p.windowSpeed,.0001);}
 private long alpha(Bitmap b){long n=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)n+=Color.alpha(b.getPixel(x,y));return n;}
 @Test public void windowStrengthAndSpeedChangeOnlyClippedGlowForEachColor(){RectF bounds=new RectF(0,0,500,300);WindowGlowRenderer renderer=new WindowGlowRenderer();for(EffectStateController.Mode mode:new EffectStateController.Mode[]{EffectStateController.Mode.COOLING,EffectStateController.Mode.HEATING,EffectStateController.Mode.PURIFICATION}){Bitmap b=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);renderer.draw(canvas,bounds,R.drawable.vehicle_top,1.3f,mode,0,1);assertEquals(0,alpha(b));renderer.draw(canvas,bounds,R.drawable.vehicle_top,1.3f,mode,20,1);long low=alpha(b);b.eraseColor(0);renderer.draw(canvas,bounds,R.drawable.vehicle_top,1.3f,mode,100,1);long full=alpha(b);assertTrue(full>low);assertEquals(0,Color.alpha(b.getPixel(250,150)));b.eraseColor(0);renderer.draw(canvas,bounds,R.drawable.vehicle_top,1.3f,mode,100,2.5f);assertNotEquals(full,alpha(b));b.recycle();}assertEquals(PsaDesign.ORANGE,AirflowRenderer.color(EffectStateController.Mode.HEATING));assertEquals(0xFF46B0FA,AirflowRenderer.color(EffectStateController.Mode.COOLING));assertEquals(0xFF42D39A,AirflowRenderer.color(EffectStateController.Mode.PURIFICATION));}
 @Test public void maximumSizeIncreasesVisibleChargingParticleArea(){ChargingParticleRenderer renderer=new ChargingParticleRenderer();Bitmap b=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);RectF bounds=new RectF(80,60,400,240);renderer.draw(canvas,bounds,360,220,1.3f,1,new EffectSettings(c).previewCharge(0,true),150,1);long normal=alpha(b);b.eraseColor(0);AppPreferences.set(c,"fx_particle_size","300");renderer.draw(canvas,bounds,360,220,1.3f,1,new EffectSettings(c).previewCharge(0,true),150,1);assertTrue(alpha(b)>normal);b.recycle();}
}
